async function logout() {
    const csrf = document.cookie.split(';').map((p) => p.trim()).find((p) => p.startsWith('vc_csrf='))?.slice('vc_csrf='.length) || '';
    const headers = { ...getRequestHeaders(), 'X-CSRF-Token': csrf };
    const result = await fetch('/auth/api/logout', { method: 'POST', headers, body: '{}' });
    if (!result.ok) { toastr.error('注销未完成，请重试。'); return; }
    location.replace('/auth/');
}
